// Per-cell pad settings. Unconfigured legacy pads keep their original behavior.
let editorPadSpeeds={4:800,5:200},pendingSpeedPad=null;
function speedPadWords(){return {ko:['가속 패드 속도','감속 패드 속도','1~1,000km/h · 통과 즉시 적용, 3초 후 레버 속도로 복귀','0~1,000km/h · 1.5초간 감속 목표로 적용. 레버 속도보다 빠르게 올리지 않습니다.','목표 속도 (km/h)','설정·배치','취소','허용 범위 안의 정수 속도를 입력하세요.','설정'],en:['Boost pad speed','Slow pad speed','1–1,000 km/h. Immediate boost for 3 seconds, then return to the lever target.','0–1,000 km/h. Slow target for 1.5 seconds; never raises the lever target.','Target speed (km/h)','Set speed','Cancel','Enter a whole-number speed within the allowed range.','Set'],ja:['加速パッド速度','減速パッド速度','1～1,000km/h。即時適用し3秒後にレバー速度へ復帰。','0～1,000km/h。1.5秒間の減速目標。レバー速度を超えません。','目標速度 (km/h)','設定','キャンセル','範囲内の整数速度を入力してください。','設定'],zh:['加速地块速度','减速地块速度','1～1,000km/h。立即生效，3秒后恢复速度杆目标。','0～1,000km/h。减速目标持续1.5秒，不提高速度杆目标。','目标速度 (km/h)','设置','取消','请输入允许范围内的整数速度。','设置']}[settings.language]||[];}
function syncEditorSpeedPad(){const type=$('editorBrush').value,active=type==='4'||type==='5';$('editorSpeedOpen').classList.toggle('hidden',!active);if(active)$('editorSpeedOpen').textContent=editorPadSpeeds[type]+' km/h '+speedPadWords()[8];}
function openSpeedPadEditor(){const type=$('editorBrush').value;if(type!=='4'&&type!=='5')return;pendingSpeedPad={type};const words=speedPadWords();$('speedPadTitle').textContent=words[type==='4'?0:1];$('speedPadValue').min=type==='4'?'1':'0';$('speedPadValue').value=editorPadSpeeds[type];$('speedPadHelp').textContent=words[type==='4'?2:3];$('speedPadLabel').textContent=words[4];$('speedPadApply').textContent=words[5];$('speedPadCancel').textContent=words[6];$('speedPadError').textContent='';$('speedPadDialog').classList.remove('hidden');$('speedPadValue').focus?.();}
function closeSpeedPadEditor(){pendingSpeedPad=null;$('speedPadDialog').classList.add('hidden');}
$('editorSpeedOpen').onclick=openSpeedPadEditor;$('speedPadCancel').onclick=closeSpeedPadEditor;
$('speedPadApply').onclick=()=>{if(!pendingSpeedPad)return;const value=Number($('speedPadValue').value),type=pendingSpeedPad.type;if(String($('speedPadValue').value).trim()===''||!Number.isInteger(value)||value<(type==='4'?1:0)||value>1000){$('speedPadError').textContent=speedPadWords()[7];return;}editorPadSpeeds[type]=value;closeSpeedPadEditor();syncEditorSpeedPad();$('editorStatus').textContent=(type==='4'?'가속':'감속')+' '+value+'km/h · 배치할 칸을 누르세요.';};
$('speedPadDialog').onclick=e=>{if(e.target===$('speedPadDialog'))closeSpeedPadEditor();};
document.addEventListener('keydown',e=>{if(pendingSpeedPad&&(e.key==='Escape'||e.code==='Escape')){e.preventDefault();closeSpeedPadEditor();}});
const speedPadPicker=chooseEditorPickerValue;chooseEditorPickerValue=function(kind,value){const out=speedPadPicker(...arguments);syncEditorSpeedPad();if(out!==false&&kind==='brush'&&(value==='4'||value==='5'))openSpeedPadEditor();return out;};
const speedPadPaint=paintEditorCell;paintEditorCell=function(r,l,batch=false){const brush=$('editorBrush').value,out=speedPadPaint(...arguments),tile=editorMap.tiles[r]?.[l];if(brush==='4'||brush==='5'){if(tile===Number(brush)){editorMap.speedPads=(editorMap.speedPads||[]).filter(p=>p.row!==r||p.lane!==l);editorMap.speedPads.push({row:r,lane:l,speedKmh:editorPadSpeeds[brush]});}}else if(tile!==4&&tile!==5)editorMap.speedPads=(editorMap.speedPads||[]).filter(p=>p.row!==r||p.lane!==l);if(!batch)renderEditorGrid();return out;};
const speedPadGrid=renderEditorGrid;renderEditorGrid=function(...args){const out=speedPadGrid(...args);syncEditorSpeedPad();for(const cell of $('editorGrid').children||[]){if(!cell.getAttribute||cell.getAttribute('data-editor-row')===null)continue;const r=Number(cell.getAttribute('data-editor-row')),l=Number(cell.getAttribute('data-editor-lane')),value=speedPadSetting(editorMap,r,l);if(value!==null){cell.textContent+=' '+value;cell.title+=' · '+value+' km/h';cell.setAttribute('aria-label',(cell.getAttribute('aria-label')||'')+' · '+value+' km/h');}}return out;};
const speedPadResize=$('editorResize').onclick;$('editorResize').onclick=()=>{const pads=editorMap.speedPads?.map(p=>({...p})),out=speedPadResize();if(pads)editorMap.speedPads=pads.filter(p=>p.row<editorMap.tiles.length&&[4,5].includes(editorMap.tiles[p.row]?.[p.lane]));renderEditorGrid();return out;};
const speedPadClose=closeEditorSheets;closeEditorSheets=function(...args){closeSpeedPadEditor();return speedPadClose(...args);};
syncEditorSpeedPad();
